@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Extensions
@inherits UmbracoViewPage<BlogFrontPage>
@{
    var posts = Model.Children<BlogPost>().OrderByDescending(p => p.PublishDate).ToList();
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.Name</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="bg-slate-50 text-slate-900">
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    <main class="mx-auto max-w-3xl px-4 py-12">
        <h2 class="mb-6 text-2xl font-bold">Latest posts</h2>
        @if (posts.Count == 0)
        {
            <p class="text-slate-500">No posts yet.</p>
        }
        else
        {
            <ul class="space-y-6">
                @foreach (var post in posts)
                {
                    <li>
                        <a href="@post.Url()" class="block rounded-lg bg-white p-6 shadow transition-shadow hover:shadow-md">
                            <h3 class="text-xl font-semibold text-indigo-700">@post.Name</h3>
                            <p class="mt-1 text-slate-600">@post.Summary</p>
                            <time class="mt-2 block text-sm text-slate-400" datetime="@post.PublishDate.ToString("yyyy-MM-dd")">@post.PublishDate.ToString("MMMM d, yyyy")</time>
                        </a>
                    </li>
                }
            </ul>
        }
    </main>
</body>
</html>

