/* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
   but content passed into their slots renders in the light DOM and is styled here. */

/* Rich text block content (Tiptap markup) */
.richtext > :first-child {
  margin-top: 0;
}

.richtext > :last-child {
  margin-bottom: 0;
}

.richtext p {
  margin-top: 1rem;
}

.richtext h2 {
  margin-top: 2rem;
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.25;
}

.richtext ul {
  margin-top: 1rem;
  padding-left: 1.5rem;
  list-style: disc;
}

.richtext li {
  margin-top: 0.25rem;
}

.richtext a {
  color: #4f46e5;
  text-decoration: underline;
}

.richtext strong {
  font-weight: 700;
}

.richtext em {
  font-style: italic;
}

